#include <string>
#include <openssl/rc4.h>

std::string compute_O_value(const std::string& user_password, const std::string& owner_password, QPDF::EncryptionData const& data) {
    // Derive RC4 key using user and owner passwords
    std::string key = owner_password + user_password;

    // Pad or truncate user password as per PDF encryption specification
    std::string padded_password = user_password;
    if (padded_password.size() > data.password_length) {
        padded_password.resize(data.password_length);
    } else if (padded_password.size() < data.password_length) {
        padded_password.resize(data.password_length, '\0');
    }

    // Initialize RC4 context
    RC4_KEY rc4_key;
    RC4_set_key(&rc4_key, key.size(), reinterpret_cast<const unsigned char*>(key.c_str()));

    // Initialize O value as a string of length equal to data.password_length
    std::string O(data.password_length, '\0');

    // Perform RC4 encryption iterations to generate O value
    for (size_t i = 0; i < data.iterations; ++i) {
        RC4(&rc4_key, padded_password.size(), reinterpret_cast<const unsigned char*>(padded_password.c_str()),
            reinterpret_cast<unsigned char*>(O.data()));
    }

    return O;
}
